class Solution:
    def numFriendRequests(self, ages: List[int]) -> int:
        n = len(ages)
        ans = 0
        for i in range(n):
            for j in range(n):
                if i == j:
                    continue
                if ages[j] <= 0.5 * ages[i] + 7 or ages[j] > ages[i]:
                    continue
                ans += 1
        return ans

