class Solution:
    def numFriendRequests(self, ages: List[int]) -> int:
        cnt = [0] * 121
        for a in ages:
            cnt[a] += 1
        ans = 0
        for a in range(1, 121):
            if cnt[a] == 0:
                continue
            lo = a // 2 + 7
            for b in range(lo + 1, a + 1):
                ans += cnt[a] * cnt[b]
                if a == b:
                    ans -= cnt[a]
        return ans

