class Solution {
public:
    int numFriendRequests(vector<int>& ages) {
        vector<long long> cnt(121, 0);
        for (int a : ages) cnt[a]++;
        long long ans = 0;
        for (int a = 1; a <= 120; a++) {
            if (!cnt[a]) continue;
            int lo = a / 2 + 7;
            for (int b = lo + 1; b <= a; b++) {
                ans += cnt[a] * cnt[b];
                if (a == b) ans -= cnt[a];
            }
        }
        return (int)ans;
    }
};

