var numFriendRequests = function(ages) {
    const cnt = new Array(121).fill(0);
    for (const a of ages) cnt[a]++;
    let ans = 0;
    for (let a = 1; a <= 120; a++) {
        if (!cnt[a]) continue;
        const lo = Math.floor(a / 2) + 7;
        for (let b = lo + 1; b <= a; b++) {
            ans += cnt[a] * cnt[b];
            if (a === b) ans -= cnt[a];
        }
    }
    return ans;
};
